-- Arbeitsrecht Berufsbildung > Wirtschaftliche Zusammenhänge > Unternehmensformen > OHG
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Haften die Gesellschafter einer IT-OHG persönlich und unbeschränkt für die Schulden der Gesellschaft?', 2, '[{"text": "Ja", "correct": true, "because": "Die OHG hat unbeschränkte persönliche Haftung"}, {"text": "Nein", "correct": false, "because": "Persönliche Haftung ist ein Merkmal der OHG"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss eine IT-OHG ein Mindestkapital bei der Gründung einbringen?', 2, '[{"text": "Nein", "correct": true, "because": "Die OHG hat kein Mindestkapital"}, {"text": "Ja", "correct": false, "because": "Kein Mindestkapital erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann eine IT-OHG von einer einzelnen Person gegründet werden?', 2, '[{"text": "Nein", "correct": true, "because": "Die OHG erfordert mindestens zwei Gesellschafter"}, {"text": "Ja", "correct": false, "because": "Mehrere Gesellschafter sind nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist eine IT-OHG verpflichtet, ihre Jahresabschlüsse beim Handelsregister einzureichen?', 2, '[{"text": "Ja", "correct": true, "because": "OHG ist als Handelsgesellschaft buchführungspflichtig"}, {"text": "Nein", "correct": false, "because": "Buchführungspflicht besteht"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann eine IT-OHG leicht gegründet werden, ohne notarielle Beurkundung?', 2, '[{"text": "Ja", "correct": true, "because": "Die OHG benötigt keine notarielle Gründung"}, {"text": "Nein", "correct": false, "because": "Keine notarielle Beurkundung nötig"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptmerkmal einer IT-OHG?', 2, '[{"text": "Unbeschränkte persönliche Haftung", "correct": true, "because": "Gesellschafter haften voll"}, {"text": "Beschränkte Haftung", "correct": false, "because": "Das gilt für GmbH"}, {"text": "Mindestkapitalanforderung", "correct": false, "because": "Kein Mindestkapital nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie viele Gesellschafter benötigt eine IT-OHG mindestens?', 3, '[{"text": "Zwei", "correct": true, "because": "OHG ist eine Personengesellschaft mit mindestens zwei Personen"}, {"text": "Einer", "correct": false, "because": "Einzelperson nicht möglich"}, {"text": "Drei", "correct": false, "because": "Zwei reichen aus"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer führt die Geschäfte einer IT-OHG?', 3, '[{"text": "Alle Gesellschafter", "correct": true, "because": "Gesellschafter führen gemeinsam die Geschäfte"}, {"text": "Ein Geschäftsführer", "correct": false, "because": "Das gilt für GmbH"}, {"text": "Ein Aufsichtsrat", "correct": false, "because": "Das gilt für AG"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Gesetz regelt die Gründung einer IT-OHG?', 2, '[{"text": "Handelsgesetzbuch (HGB)", "correct": true, "because": "HGB regelt die OHG"}, {"text": "GmbHG", "correct": false, "because": "Gilt für GmbH"}, {"text": "BBiG", "correct": false, "because": "Regelt Ausbildung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Vorteil der OHG als Unternehmensform für einen IT-Betrieb?', 3, '[{"text": "Einfache Gründung", "correct": true, "because": "Keine notarielle Beurkundung nötig"}, {"text": "Beschränkte Haftung", "correct": false, "because": "OHG haftet unbeschränkt"}, {"text": "Hohe Kapitalanforderung", "correct": false, "because": "Kein Mindestkapital nötig"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat eine IT-OHG?', 4, '[{"text": "Unbeschränkte persönliche Haftung", "correct": true, "because": "Gesellschafter haften voll"}, {"text": "Mindestens zwei Gesellschafter", "correct": true, "because": "OHG ist Personengesellschaft"}, {"text": "Mindestkapital von 25.000 Euro", "correct": false, "because": "Kein Mindestkapital nötig"}, {"text": "Einfache Gründung", "correct": true, "because": "Keine notarielle Beurkundung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die OHG als Unternehmensform für einen IT-Betrieb?', 3, '[{"text": "Einfache und kostengünstige Gründung", "correct": true, "because": "Keine hohen Gründungskosten"}, {"text": "Gemeinsame Geschäftsführung", "correct": true, "because": "Gesellschafter führen gemeinsam"}, {"text": "Beschränkte Haftung", "correct": false, "because": "OHG haftet unbeschränkt"}, {"text": "Flexibilität bei Entscheidungen", "correct": true, "because": "Gesellschafter entscheiden direkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat die OHG als Unternehmensform für einen IT-Betrieb?', 4, '[{"text": "Unbeschränkte Haftung", "correct": true, "because": "Gesellschafter haften persönlich"}, {"text": "Buchführungspflicht", "correct": true, "because": "Als Handelsgesellschaft vorgeschrieben"}, {"text": "Hohe Gründungskosten", "correct": false, "because": "Gründung ist kostengünstig"}, {"text": "Risiko durch Mitgesellschafter", "correct": true, "because": "Fehlentscheidungen treffen alle"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche rechtlichen Anforderungen gelten für eine IT-OHG?', 3, '[{"text": "Eintragung ins Handelsregister", "correct": true, "because": "OHG ist Handelsgesellschaft"}, {"text": "Buchführung nach HGB", "correct": true, "because": "Pflicht für Handelsgesellschaften"}, {"text": "Mindestkapital von 25.000 Euro", "correct": false, "because": "Kein Mindestkapital nötig"}, {"text": "Veröffentlichungspflicht der Bilanz", "correct": true, "because": "Pflicht je nach Größe"}]'),
('00000000-0000-0000-0000-000000000000', 'Was unterscheidet die OHG von einer GmbH für einen IT-Betrieb?', 3, '[{"text": "OHG hat unbeschränkte Haftung", "correct": true, "because": "GmbH haftet beschränkt"}, {"text": "GmbH benötigt Mindestkapital", "correct": true, "because": "OHG hat kein Mindestkapital"}, {"text": "OHG hat weniger Gründungskosten", "correct": true, "because": "Keine notarielle Beurkundung"}, {"text": "GmbH hat einfachere Buchführung", "correct": false, "because": "GmbH hat strengere Anforderungen"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Die OHG haftet unbeschränkt mit dem Privatvermögen. b) Eine IT-OHG benötigt ein Mindestkapital.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Haftung ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Eine IT-OHG kann einfach gegründet werden. b) Eine OHG benötigt mindestens zwei Gesellschafter.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "Einfache Gründung und zwei Gesellschafter"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Eine IT-OHG ist buchführungspflichtig. b) Eine OHG kann von einer Person gegründet werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Buchführung ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Die OHG bietet Flexibilität bei der Geschäftsführung. b) Die OHG haftet nur mit dem Gesellschaftsvermögen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Flexibilität ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Eine IT-OHG ist eine Personengesellschaft. b) Eine OHG benötigt eine notarielle Beurkundung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Personengesellschaft ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

